// DeepPartial：递归可选，排除函数和数组
export type DeepPartial<T> = T extends (...args: any[]) => any
  ? T
  : T extends Array<infer E>
    ? Array<DeepPartial<E>>
    : T extends object
      ? { [K in keyof T]?: DeepPartial<T[K]> }
      : T;

// 验证
interface Config {
  name: string;
  nested: { a: number; b: boolean[] };
  handler: (x: number) => void;
}
type PartialConfig = DeepPartial<Config>;
// { name?: string; nested?: { a?: number; b?: DeepPartial<boolean[]> } }

// 元组操作
type Head<T extends any[]> = T extends [infer H, ...any[]] ? H : never;
type Tail<T extends any[]> = T extends [any, ...infer R] ? R : never;
type Last<T extends any[]> = T extends [...any[], infer L] ? L : never;

type H1 = Head<[1, 2, 3]>; // 1

type L1 = Last<[1, 2, 3]>; // 3

// 字符串逐字符解析（模式匹配 + 递归）
type StringToUnion<S extends string> =
  S extends `${infer H}${infer T}` ? H | StringToUnion<T> : never;
type SU = StringToUnion<'abc'>; // 'a' | 'b' | 'c'

// 字符串转元组（带长度计数）
type Split<S extends string, R extends string[] = []> =
  S extends `${infer H}${infer T}` ? Split<T, [...R, H]> : R;
type SA = Split<'abc'>; // ['a', 'b', 'c']

// 类型层面加法（元组长度）
type BuildTuple<N extends number, T extends any[] = []> =
  T['length'] extends N ? T : BuildTuple<N, [...T, any]>;
type Add<A extends number, B extends number> =
  [...BuildTuple<A>, ...BuildTuple<B>]['length'] & number;
type Sum = Add<2, 3>; // 5

// Chainable Options：每次 option 返回扩展后的类型
type Chainable<T extends object = {}> = {
  option<K extends string, V>(
    key: K extends keyof T ? never : K,
    value: V
  ): Chainable<T & Record<K, V>>;
  get(): T;
};

function chainable(): Chainable {
  const store: Record<string, any> = {};
  return {
    option(key, value) {
      store[key] = value;
      return this;
    },
    get() {
      return store as any;
    }
  };
}

const config = chainable()
  .option('name', 'hello')
  .option('age', 42)
  .get();
// 类型：{ name: string; age: number }
